  "policy": "Keep QP tariffs; retain report guidance as qualified evidence. Do not repair official sources or copy their inconsistencies into learner material.",
  "entries": [
    {
      "source": "6145-2020-ER",
      "pdf_page": 148,
      "question": "P2 2(c)",
      "issue": "QP prints 3 marks; the report's suggested-answer table prints 4 and describes identification plus up to three description marks.",
      "resolution": "Evidence record retains the QP tariff of 3. Do not import the report's four-mark composition."
    },
    {
      "source": "6145-2023-ER",
      "pdf_page": 177,
      "question": "P1 25(c)",
      "issue": "QP prints 7 marks; report labels the evaluation up to 6, with a 4–5 upper band and a conclusion mark.",
      "resolution": "Retain 7 as the observed QP tariff. Record the need for developed judgement without claiming the inconsistent report is a complete seven-mark allocation."
    },
    {
      "source": "6145-2023-ER",
      "pdf_page": 179,
      "question": "P1 26(c)",
      "issue": "Report table prints 7 but its prose says evaluation up to 5; the adjacent upper band is 4–6 plus a decision mark.",
      "resolution": "Retain the QP tariff of 7; do not generalise the up-to-five statement."
    },
    {
      "source": "6145-2023-ER",
      "pdf_page": 180,
      "question": "P1 26(d)",
      "issue": "QP and report column print 6; guidance includes a 4–6 upper band and also mentions a conclusion mark. It also refers to diminishing returns while discussing economies/diseconomies of scale.",
      "resolution": "Keep 6 total; distinguish long-run scale effects from short-run diminishing returns. Do not add an unsupported seventh mark or teach the two mechanisms as equivalent."
    },
    {
      "source": "6145-2023-ER",
      "pdf_page": 187,
      "question": "P2 3(c)",
      "issue": "QP prints 6; report describes a 4–6 upper band and additionally describes a conclusion mark.",
      "resolution": "Retain 6 total; use the balanced-argument demand without inventing a seventh mark."
    },
    {
      "source": "6145-2024-ER",
      "pdf_page": 187,
      "question": "P2 6(d)",
      "issue": "The commentary refers to developed countries, while the QP asks about problems of a developing country as it becomes more developed.",
      "resolution": "Follow the QP's transition/development demand; avoid copying the commentary's changed scope."
    },
    {
      "source": "6145-2020-P1",
      "question": "24(b)(ii)",
      "issue": "The extract combines drought, herd losses and quality-related price changes while asking for a supply-elasticity calculation. Simultaneous shifts and quality changes do not identify a causal supply elasticity on their own.",
      "provenance": "analytical judgement about the scenario, not an official correction",
      "resolution": "Mine the numerical demand and tariff. Author a new clean, conditioned example rather than treating the observational narrative as proof of a supply law."
    }
  ]
}

